async function renderMemory(){const d=await api('memory?page='+memoryPage);const m=cfg.memory;$('#content').innerHTML=head('MEMORIES THAT STAY','长期记忆','独立归档你的对话。压缩、换会话与重启，都不会让它消失。',saveButton())+pending()+`<div class="stats-grid">${stat('归档消息',d.stats.messages||0,'包含软删除记录','条')}${stat('对话对象',d.stats.peers||0,'按平台身份隔离','位')}${stat('已遗忘记录',d.stats.deleted||0,'软删除，不参与召回','条')}${stat('自动召回',m.recallEnabled?'已开启':'已关闭','每次最多 '+m.recallMax+' 条')}</div>`+panel('归档与召回',`<div class="two-col"><div>${toggle('memory','archiveEnabled','记录新消息',m.archiveEnabled,'关闭后不再把新消息写入独立记忆库。')}${toggle('memory','recallEnabled','自动召回旧对话',m.recallEnabled,'只注入相关历史，不主动发起回复。')}</div><div class="form-grid">${numberField('memory','recallMax','每次召回条数',m.recallMax,0,null)}${numberField('memory','recallCooldownSec','召回冷却（秒）',m.recallCooldownSec,0,null)}${numberField('memory','maxTextChars','单条归档字数上限',m.maxTextChars,0,null,'0 表示完整保存，不截断。')}${numberField('memory','minQueryChars','最短召回问题字数',m.minQueryChars,0,null)}</div></div>`)+panel('对话原文',`<form id="memory-search" class="toolbar"><input class="search" id="memory-query" placeholder="搜索历史里的一个词或一句话"><select id="memory-peer"><option value="">全部对话对象</option>${d.peers.map(p=>`<option value="${esc(p.peer)}">${esc(p.peer.slice(0,8))}… · ${p.count} 条</option>`).join('')}</select><button class="secondary">搜索</button></form><div id="memory-records"></div><div class="pagination"><button class="small-button" id="memory-prev">上一页</button><span id="memory-page"></span><button class="small-button" id="memory-next">下一页</button></div>`,'仅在已登录管理台中查看');drawRecords(d);bindSave();$('#memory-search').onsubmit=e=>{e.preventDefault();memoryPage=0;searchMemory()};$('#memory-prev').onclick=()=>{if(memoryPage>0){memoryPage--;searchMemory()}};$('#memory-next').onclick=()=>{memoryPage++;searchMemory()}}
