async function sessionDetail(id){
 $('#session-detail').innerHTML='<div class="loading"><span class="spinner"></span>读取会话原文、思考记录与结束状态…</div>';
 try{const d=await api('calls?sessionId='+encodeURIComponent(id));
  $('#session-detail').innerHTML=panel('最近对话原文',`<div class="records">${(d.messages||[]).filter(m=>m.text||m.thinking).map(m=>`<article class="record"><div class="record-head"><span>${m.role==='user'?'用户':'大鲸鱼'}</span><span>${date(m.ts)}</span></div><p>${esc(m.text||'（本轮没有最终文本，可能只有工具调用）')}</p>${m.thinking?`<details class="thinking-block"><summary>查看本轮思考记录 · ${Number(m.thinking.length).toLocaleString()} 字</summary><pre class="thinking-text">${esc(m.thinking)}</pre></details>`:''}</article>`).join('')||'<div class="empty">暂无可展示的对话或思考。</div>'}</div>`,'思考记录默认折叠 · 旧模型记录保留原文')+`<div class="toolbar"><button class="secondary" id="detail-thinking-all">查看此会话全部思考历史</button></div>`;
  $('#detail-thinking-all').onclick=()=>openThinking(id);
  $('#session-detail').scrollIntoView({behavior:'smooth',block:'start'});
 }catch(e){$('#session-detail').innerHTML=`<div class="note warn">${esc(e.message)}</div>`}
}
